{"path": "csvfix/impl.py", "content": "def parse(line):
    """Split a CSV line into exactly 3 trimmed fields.

    Returns None when the line does not have exactly 3 columns.
    """
    if line is None:
        return None
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 3:
        return None
    return fields


def total(rows):
    """Sum the third column (the amount), skipping blank amount fields."""
    result = 0
    for row in rows:
        if row is None or len(row) < 3:
            continue
        amount = row[2].strip() if isinstance(row[2], str) else row[2]
        if amount == "" or amount is None:
            continue
        result += int(amount)
    return result
"}

{"path": "rules/engine.py", "content": "def _truthy(value):
    return bool(value)


def evaluate(rules, facts):
    """Evaluate a rule against facts.

    Supported rule shapes:
      {"all": [fact, ...]} -> True when every named fact is truthy
      {"any": [fact, ...]} -> True when at least one named fact is truthy
    """
    if not isinstance(rules, dict) or len(rules) != 1:
        raise ValueError("rule must be a single-key dict with 'all' or 'any'")

    (op, names), = rules.items()
    names = list(names or [])

    if op == "all":
        return all(_truthy(facts.get(name, False)) for name in names)
    if op == "any":
        return any(_truthy(facts.get(name, False)) for name in names)
    raise ValueError("unsupported rule operator: %r" % (op,))
